"""Inspect SQLite databases in the workspace to learn their schema.

This helper only reads local database metadata and sample rows; it never
modifies anything.
"""

import os
import sqlite3

DB_EXTENSIONS = (".db", ".sqlite", ".sqlite3")


def find_db_files(root: str = ".") -> list[str]:
    """Return paths of SQLite database files under *root*."""
    matches: list[str] = []
    for dirpath, dirnames, filenames in os.walk(root):
        # Skip hidden directories (e.g. .git, .venv) to avoid noise.
        dirnames[:] = [d for d in dirnames if not d.startswith(".")]
        for name in filenames:
            if name.lower().endswith(DB_EXTENSIONS):
                matches.append(os.path.join(dirpath, name))
    return matches


def describe_db(path: str) -> None:
    """Print tables, columns, row counts, and one sample row per table."""
    print(f"=== {path} ===")
    with sqlite3.connect(path) as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.cursor()
        tables = cur.execute(
            "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
        ).fetchall()
        if not tables:
            print("(no tables)")
            return
        for table in tables:
            table_name = table["name"]
            print(f"--- table: {table_name} ---")
            cols = cur.execute(f'PRAGMA table_info("{table_name}")').fetchall()
            for col in cols:
                print("  ", dict(col))
            count = cur.execute(
                f'SELECT COUNT(*) FROM "{table_name}"'
            ).fetchone()[0]
            print(f"  row count: {count}")
            sample = cur.execute(
                f'SELECT * FROM "{table_name}" LIMIT 1'
            ).fetchone()
            if sample is not None:
                print("  sample row:", dict(sample))


def main() -> None:
    db_paths = find_db_files()
    if not db_paths:
        print("NO_DB_FILES_FOUND")
        return
    for path in sorted(db_paths):
        describe_db(path)


if __name__ == "__main__":
    main()

